) AS (
  VALUES 
    (188::BIGINT, 'Jorge es muy buen profesor a la hora de de su clase, con sus charlas al inicio de cada clase inspira a mejorar junto a ejercicios (que sincero suelen ser bastantes pesados) son muy buenos y te ayudan a mejorar, es muy cómico a la hora de dar las clases y me divertí en cada una de ellas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, '69516cee3d89c7946ed9d77d83e35ba77c57bb6b054340a12fd7cd80cc059bf7'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Excelente profesor. Siempre empieza la clase brindando consejos sobre la vida que son demasiado provechosos. Las clases son súper divertidas y aunque el curso de acondicionamiento es pesado por el tipo de ejercicios, la clase es bastante amena.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, '4ef31e676ca3c7ade780560de97f6efa5b8f4ba26f7a9404489bb8f297b8a255'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'De los mejores profes que se va topar en la U. Siempre da una charla motivacional antes de la clase, probablemente te termine gustando jugar no lo dude en matricular con él cualquier curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, '2b7ac0e3820f533dbe79048fd0fe72d653c410177a132d55c1d5942be8a13c6a'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Muy buen profesor, entiende la vida estudiantil y cae bien. La clase es vacilona y puede que les guste sin saberlo de antemano. ¡No duden en llevar una clase con él!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, '0fd692ab62cb0c977e20aeba8d1909e9578325da0cda2214dd7f8493e2d35acb'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Excelente profesor y ser humano. Da charlas motivacionales al incio de la clase, promueve la socialización con los compañeros, y finalmente, el curso se pasa con solo asistir y disfrutar de las diversas actividades. 100% recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2024-08-11T00:00:00+00:00'::TIMESTAMPTZ, '6585dacc0cae59407455a0c4fed3593fca618a90736b358c7beb52a33c3186ee'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, '10/10, desde antes de conocerlo me cayó bien, nos daba charlas motivacionales al inicio de las clases y nos daba buena retroalimentación al jugar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f74407dce29aeaa79766a9463acfeed845ba7ac38e40bf86d83fc0ca9b61a9a4'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Con solo dar lo mejor de uno mismo en la clase es suficiente, lo inspira a uno a seguir intentando y busca hacer que las clases sean lo más divertidas posibles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'bac0a6fb0cf35a0ca1896cdd8172aa6a1f7ec85856dac80daf8bc9e57def63f0'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'La clase es muy divertida. A final de semestre da como dos o tres clases para poder reponer ausencias. Hace una que otra charla motivacional en las clases. Un muy buen profe, si pueden llevar con él háganlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'a97d52ed731e77a3ce385790ea1ae591a89a4dc694e7888b4ed2b01449f6fc9d'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Gran profesor, comprometido con que uno aprenda y disfrute el deporte, trabaja muy bien la parte social incluyendo temas de liderazgo y como se aplica a la vida y al deporte'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'f8ef86eb08fb6489e1e9f28f30455069fab7a9a5c86312dde3bd2929228e4083'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Hace el curso algo fuerte, pero también entretenido. El profe es muy consciente de que conforme avanza las semanas, uno está más exhausto por el semestre. Me gustó que cada uno podía ir a su ritmo, definitivamente mejora su condición y el profe lo motiva a uno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'fa195def7c1e1da714dcf71be7542c975587f391b84b286995d1d656320c944e'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Es un excelente profesor, siempre empieza con una charla motivacional y se preocupa por el bienestar físico y mental de los estudiantes. El mejor profesor para llevar deportivas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, '45dabda123497acf338cae78f69645a3c0477be2d9cc51d3555b9a9bf2a9362b'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Super facil, solo asistiendo se pasa, el profe es super pura vida, y llevar la materia es demasiado aliviante es comparación a lo demás, recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '2e355e570d7ce76e3041383cb395a90489b7f4da4f88f24f497dd51e2b88a7b7'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Fue la clase que mas disfruté del semestre, increible persona y profe. Las clases no son cansadas, si lo pudiese llevar de nuevo lo llevaría.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '735c4f666a2b1f4e9e2a5c5606ff9724013ed5acb808ca3a6da6ef27fba266ba'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Es un curso que si se tiene disposición se hace super divertido. Hay partidos entre grupos que son bastante buenos. Si pretende faltar a clases las dos veces que se pueden hacer, no pueden ser las dos últimas clases, le recomiendo que una de esas sea la 2nda clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2023-06-12T00:00:00+00:00'::TIMESTAMPTZ, '47df3d0de9a57c87b0064f7058d0d66bbacb84bc6dd3122dd942e8de70fc2241'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Es el mejor profe de la escuela, sus clases son entretenidas, no son cansadas, es súper comprensivo, simplemente es excelente, no dude dos veces en matricular y va a ver que se convertirá en su clase favorita de la semana'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'df1d023522897732016c92927b65bd842d80a68e865dbc9653a211ad0d790c2e'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'El profe cae súper bien, hace actividades entretenidas. Siempre da una mini-charla motivacional antes de cada clase, si hay que entregar trabajos es flexible con la entrega.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-30T00:00:00+00:00'::TIMESTAMPTZ, '2ebb533d6e374b58aec388e4fae026604bed4b4323f5ce0fdd3305abcef4d479'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Si falta a 3 clases se queda. Hace una mini charla inicial para motivar y luego empieza la clase, a veces circuitos de ejercicios o actividades en grupos. Consígase uno o varios compas porque siempre pide parejas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2022-11-27T00:00:00+00:00'::TIMESTAMPTZ, '1ed15496d45695c877ba2fa8138893e7a213b5a1c956d82b0b1389735c8e9e12'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'De los mejores profes, hace la clase muy entretenida y ayuda a desestresarse, ayuda bastante, el curso con él es divertido,'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, '3943b11dea0bd69fb4f22ab390a7a31aabefac315a84a2c6fa5bd4a950e225eb'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Es un muy buen profe y la materia es una excelente deportiva para llevar. Se hacía una semana virtual donde hacíamos ejercicios en casay otra presencial donde jugábamos . En general se pasa un rato muy agradable y de despeje. El profe es muy comprensivo y apoya si uno muestra interés'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '5193893229e853fe4f168da7edebcc12e49e353ffd2f81a7de33e9940341b859'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'El profesor es excelente. Se preocupa por los estudiantes y hace de su clase un rato para distraerse de la carga académica. Trabaja con portafolio, el cual se llena todas las semanas únicamente con comentarios cuando la clase es sincrónica, pero cuando la clase es asincrónica, sí lleva evidencia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'a325d840ef9910f6781bb0ffe8a44f01ea55d50cd18ef1cbdc5ad5caab174a53'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Hay que hacer un portafolio semanal pero no se dura mucho haciéndolo. Pide evidencias en video pero no todas las semanas. No es obligatorio encender la cámara para los ejercicios. El profe es muy comprensivo y se preocupa mucho por la salud mental de los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, '218228346a80f98a69dc7b3bf7e4d6659422b1f91c33b92aa276bbf6f698d489'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Muy buen profe y las clases son muy entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '7e46b75101c1da9dd2de97522988e5a00caa590b61766b7a643950d67c80ae3d'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Cada semana tiene que hacer una bitacora pero es pequeña que no dura ni 30 minutos. El profe se esfuerza en hacer la clase interesante aun estando virtual. Completamente recomendado si necesita una deportiva estando virtual.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'e2528c39ecfc6951527a5a966502dc17aa7b18a42377c4b0e4f925fc956b2227'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Debe realizar un portafolio cada semana, pero no quita mucho tiempo, así que si debe meter una deportiva, esta es una buena opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'f295bfeb23b4d292dc0f41e21eb096a43ed9d301ec634c935c4de709eb9ffe0e'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Súper fácil de pasar, la mayoría de clases asincrónicas y se ven videos o juegos com los compañeros!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '1fa905653e7c0f02be3e8464e875544923daa65a1533e7bb890b04f59ba91e39'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'La clase se pasa solo con asistir. El profe da mucha charla inspiracional al inicio, y se esfuerza para hacer una clase entretenida. Cada semana tiene que hacer un portafolio, con evidencias y una hoja con recomendaciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, '90009234faa7ee099e0e8dbf3b9cb0e8a8cacc6f97e058781698dc0d83fa10e3'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Como toda deportiva, se pasa con solo asistir a clases, el profe es una excelente persona. Las clases son duras en cuanto a esfuerzo físico, mas si eres alguien que no suele ejercitar constantemente. Sin embargo son clases entretenidas, pero sobretodo agotadoras'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'b758594d20e879d67012cbdf1170b1bc861d3f4c7fcf3f8b0775673e66ecbbf7'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'El mejor profe de la vida! Super atento y buena gente, motiva a los estudiantes y quiere lo mejor para ellos. Llevé el curso virtual y es muy llevadero. Hay que hacer informes semanales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '7a720d89a99eabe1edf138e8241ecb3c97bd4a3936d21c88229805c80de35e40'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '613f46c16aae14be0f9a85d0f7607438944d9a45cb91fb7bcd28481844e4ffbf'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Excelente y se acomodó muy bien a la modalidad virtual, es perfecto si quieren hacer ejercicio en casa. Siempre está abierto a retroalimentación, súper bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'fe18c1c3ca1261e9642b194da64941f0e1d4e50845f474ceb245c2b3419dfc0e'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Muy buena gente, le motiva al estudiante y gran profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '813cf62d02e981df7295b875404e29155f219299b932ad5c4d3983728ef715d8'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Es un buen profe, pero bastante exigente para ser una deportiva. Si le gusta el deporte la clase se disfruta bastante'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-01-27T00:00:00+00:00'::TIMESTAMPTZ, '64b28b7cee69e417fb8f7b06c74c0a4156f17c5c9fdb574b1823e8f6fa15061e'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Usted de verdad aprende, el profe se lo toma en serio, es super buena gente y es inspiracional, lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2019-11-19T00:00:00+00:00'::TIMESTAMPTZ, '35729b09fa5fa34fa2e0c2408c473c96e9b0a4a9a2e19e203d6e02640d349af4'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5922f4923be4e544d029d129178e3c2add0f5aefe18cbd5b40ca23a0f57daf71'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'El profe es super lindo y pura vida, al principio de cada clase da una mini charla motivacional que de verdad le llega a uno. Yo tengo una condición física bien mala y él siempre lo motiva a uno a mejorar. Volvería a meter con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '6b87fcb70cd55d86c032c739bb57651c36fd04b34e7594a5a7187c034f40429c'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Es el mejor porfe las clases son divertidas, siempre tiene algo positivo que decir, al principio de todas las clases da una pequeña charla de motivacion, es muy flexible con la asistencia y las calificaciones'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '02baeab0b3e75d8def4d1b36c524eb0cc894801b600b8a0a996bb390a36d0930'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Muy buen profe. Da buenos consejos y retroalimentación durante el curso. No hace falta ser un especialista en cada deporte para poder disfrutar la clase. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2019-06-10T00:00:00+00:00'::TIMESTAMPTZ, '73fbcc4ef21a403198c117c470f023faeee54827e1219686589162f47d5fe7da'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Siempre da charlas motivacionales antes de la clase. Las clases siempre son muy divertidas. Al final del curso organiza alguna comida dependiendo del horario de la clase. La última clase da la nota y le dice cuál era la primera impresión que tuvo y la que tiene actualmente de usted.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2018-12-25T00:00:00+00:00'::TIMESTAMPTZ, 'e7e13ed8419f6c2a9ebfb43a727e9b6f84f5327d72227fb4fe469429e938ce62'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Cansado, pero excelente profe :). Da unos minutos motivacionales al inicio de las clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '50e64b9f0ba8f5ef624baeddc48b991efa3cee2be37e2dc04cba5480d644bb00'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'El mejor profe sus clases son muy motivadoras, cada quien va a su propio paso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2018-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'a98837e102f56c2df20c28aaa2d7ba2bdd201612992ff54541946223ac93f9e6'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Muy motivador y buena gente, la clase es matada pero lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-12T00:00:00+00:00'::TIMESTAMPTZ, '47ae36058456faec71c31b46147443d4e075a2d908b1b330c13780aeeaa152bf'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Super recomendado para las personas que no quieran practicar un solo deporte todo un semestre, clases divertidas y diferentes, solo pide un trabajo en todo el semestre y dos actividades extra'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '052d6dcec79392011ac1d240239672c4afffbba0f793c447c7b1cef5845b479d'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Un profe muy atento, solo hay que asistir a clase y ser participativos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '31dd95961725214173af212a08a348de48bdb2cdd29c223aa343352b5fbc6285'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'El profe es una teja, lo inspira a uno a hacer ejercicio, sin embargo, si usted no es de hacer mucho deporte mejor no meta este curso, porque va a morir jaja.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '7605cc981fe4b03ba4ee464c3e056050348bb4a9f11f6f3d57fb29466c99ef6e'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'De verdad si tiene la oportunidad de matricular con él no lo dude ni un segundo, es un excelente profe, no califica duro y las clases son muy entretenidas, RECOMENDADO.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-11T00:00:00+00:00'::TIMESTAMPTZ, '3cce0cf1dfcac96fe3ed038ca663e8a6ef88a1410e21206ca2affcdc795446c6'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2018-01-22T00:00:00+00:00'::TIMESTAMPTZ, '7fc019af3be44bcc6708989d5a101e9dda76a540a8a06179d1ef8b4f49954424'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Un profesor excelente! Al inicio de cada clase da pequeñas charlas motivacionales muy chivas, las clases son super entretenidas, deja un trabajo super simple. Super recomendado!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2018-01-16T00:00:00+00:00'::TIMESTAMPTZ, '1b42ea74df8190d87e9961cde3ac62de7af0d4b7c7328ec45da2753030f3316a'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-02T00:00:00+00:00'::TIMESTAMPTZ, 'f373c51d9b8c11cb551543060e1a56cf873a8c79a39fa383bdcdfa6abbd4e0c3'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Da una buena y MUY interesante charla al inicio de la clase bastante motivacional. Las clases son duras, yo practico ejercicio regularmente e igual tenía que parar, pero los ejercicios los adapta a su condición. SÚPER RECOMENDADO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c8669125c4514eae090c2a27be4d9f8733bafd801f30fd9e23c1c8182ea79883'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '28e22d4a34326ff6be69da176deea9f0e193bd978eac82c5a5aac5f83c93f478'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Muy buena persona, ayuda mucho. Solo hay que ser responsable y no pensar que es cualquier clase. Es cansadillo, pero tampoco se mata uno haciendo el ejercicio semanal aunque sea'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'e9eb6a6f06fdf9389a7152911845eaf1a50f2abe234033f87da9e3784b7d5ee2'::TEXT, ARRAY[578]::BIGINT[]),
    (188::BIGINT, 'Muy buena gente, hace que la clase sea divertida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd24f4464302cebfbd37fe0b5b10bf7eead73d260bd5a4236d51621bd9ed50032'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'El profe es súper buena gente, algunas clases son bastante cansadas pero no insoportables. Se hacen muchos juegos y ejercicios en pareja lo cual sirve mucho para socializar, al final del semestre es casi imposible dejar de hablar. Esta clase me ayudo un montón a liberar algo de estrés.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, '401d5d12294d21edb18c38ae2a0f53f0c53be54cbde2bbb0272df51d836a45c2'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Excelente profe, pero más que el profe en sí, lo que recomiendo es Acondicionamiento físico con él. La clase puede ser un poco matada desde el calentamiento hasta el final, pero es muy chiva si usted es de esas personas que nunca practican deporte (como para ejercitarse de vez en cuando)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'e5ce2156e9b581a8d58b9e06e84f855714a170edb9d9caf2bff150374fd67613'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '0c25722707db9bab934c1b2b3acbc27f3bb6ae4f5e1fceb2c14799d28deb44e5'::TEXT, ARRAY[493]::BIGINT[]),
    (188::BIGINT, 'Bastante fuerte a la hora de poner ejercicios, pero se disfruta. Gracias a esta clase conocí todo el campus en una salida a correr de la clase (por detrás de MADI y Maderas). Se tiene que hacer un pequeño trabajo, pero es súper fácil. El profe es muy buena nota y se preocupa por los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '04711cd9d048beaa5a8ed3596343901a2c4269fc8ab90330526c99eb7397dd4d'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Bastante Actividad Fisica... un poco difícil para los que no hacen ejercicio pero al final para eso es el curso :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2016-04-27T00:00:00+00:00'::TIMESTAMPTZ, 'd1c4fa4bbc41ac8dd98191068f96a3137421df161deb7d932a086e271bcfd7f1'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Es muy cansado para los que no hacen mucha actividad física, pero se divierte mucho. Es muy buena gente, pero se debe ser participativo. Me ayudó mucho para olvidarme de la carga de la semana. Muy buen profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, '5b5a583dfa122cd9789bfc237f38dbc9de6527c048169a402a4439e1e8e51bbb'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'fe36d12ed54e20dafda5f984c9e108d9b971258da085759a2e2d2fe0e997136f'::TEXT, ARRAY[494]::BIGINT[]),
    (188::BIGINT, 'Se ven bastantes deportes entonces se disfruta la clase, sólo requiere de hacer un pequeño trabajo al final que no requiere mucho esfuerzo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-24T00:00:00+00:00'::TIMESTAMPTZ, '0afb9a511127f28463fb6a5fbb682fde06be60668a5e6e91b50821a3bab53833'::TEXT, ARRAY[493]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
